    def typed(self, func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            signature = self.type_annotations.get(func.__name__)
            if signature:
                for i, (arg, expected_type) in enumerate(zip(args, signature["args"])):
                    if not isinstance(arg, expected_type):
                        raise TypeError(f"Argument {i+1} of {func.__name__} should be of type {expected_type.__name__}")

                result = func(*args, **kwargs)
                if not isinstance(result, signature["return"]):
                    raise TypeError(f"Return value of {func.__name__} should be of type {signature['return'].__name__}")

                return result
            else:
                return func(*args, **kwargs)

        return wrapper

_tc = Config()
typed = _tc.typed
TypeError = _tc.TypeError
ValueError = _tc.ValueError

__all__ = ("typed", "TypeError", "ValueError")
```

