import UIKit

class ViewController: UIViewController {

    @IBOutlet weak var tipControl: UISegmentedControl!
    @IBOutlet weak var billField: UITextField!
    @IBOutlet weak var totalLabel: UILabel!

    override func viewDidLoad() {
        super.viewDidLoad()
        // Initialize the billField and totalLabel properties
    }

    @IBAction func billAmountChanged(_ sender: Any) {
        guard let billAmountText = billField.text, let billAmount = Double(billAmountText) else {
            return
        }
        let selectedTipPercentage = getSelectedTipPercentage()
        calculateTotalAmount(billAmount: billAmount, tipPercentage: selectedTipPercentage)
    }

    @IBAction func tipPercentageChanged(_ sender: Any) {
        let selectedTipPercentage = getSelectedTipPercentage()
        if let billAmountText = billField.text, let billAmount = Double(billAmountText) {
            calculateTotalAmount(billAmount: billAmount, tipPercentage: selectedTipPercentage)
        }
    }

    func calculateTotalAmount(billAmount: Double, tipPercentage: Double) {
        let tipAmount = billAmount * (tipPercentage / 100)
        let totalAmount = billAmount + tipAmount
        totalLabel.text = String(format: "$%.2f", totalAmount)
    }

    private func getSelectedTipPercentage() -> Double {
        switch tipControl.selectedSegmentIndex {
        case 0:
            return 15.0
        case 1:
            return 20.0
        case 2:
            return 25.0
        default:
            return 0.0
        }
    }
}
