### Problem:
You are tasked with implementing a function that can parse and extract comments from a given piece of C# code. The comments can be of two types: single-line comments starting with `//` and multi-line comments enclosed within `/*` and `*/`. Your function should return a list of all the extracted comments in the order they appear in the code.

Function Signature: `List<string> ExtractComments(string code)`

Input:
- `code` (1 <= |code| <= 10^5) : A string representing the C# code from which comments need to be extracted. The code may contain single-line comments, multi-line comments, or both.

Output:
- A list of strings, where each string represents a comment extracted from the code. The list should maintain the order of appearance of the comments in the code.

Example:
```
Input:
code = @"
        // This is a single-line comment
        int x = 5; // This is another single-line comment
        /*
        This is a multi-line comment
        spanning multiple lines
        */
        string y = ""Hello""; // This is a single-line comment at the end
        "
Output:
["This is a single-line comment", "This is another single-line comment", "This is a multi-line comment\nspanning multiple lines", "This is a single-line comment at the end"]
```

Note:
- The input code may contain single-line comments, multi-line comments, or both.
- Comments can appear at the beginning, middle, or end of a line.
- Multi-line comments can span multiple lines and can contain any characters, including newlines.

### Solution:
```csharp
using System;
using System.Collections.Generic;
using System.Text;

class Program
{
    static List<string> ExtractComments(string code)
    {
        List<string> comments = new List<string>();
        bool inSingleLineComment = false;
        bool inMultiLineComment = false;
        StringBuilder currentComment = new StringBuilder();

        for (int i = 0; i < code.Length; i++)
        {
            if (inSingleLineComment)
            {
                if (code[i] == '\n')
                {
                    comments.Add(currentComment.ToString().Trim());
                    currentComment.Clear();
                    inSingleLineComment = false;
                }
                else
                {
                    currentComment.Append(code[i]);
                }
            }
            else if (inMultiLineComment)
            {
                if (code[i] == '*' && i < code.Length - 1 && code[i + 1] == '/')
                {
                    comments.Add(currentComment.ToString().Trim());
                    currentComment.Clear();
                    inMultiLineComment = false;
                    i++; // Skip the '/' character
                }
                else
                {
                    currentComment.Append(code[i]);
                }
            }
            else
            {
                if (code[i] == '/' && i < code.Length - 1)
                {
                    if (code[i + 1] == '/')
                    {
                        inSingleLineComment = true;
                        i++; // Skip the second '/' character
                    }
                    else if (code[i + 1] == '*')
                    {
                        inMultiLineComment = true;
                        i++; // Skip the '*' character
                    }
                }
            }
        }

        if (inSingleLineComment || inMultiLineComment)
        {
            comments.Add(currentComment.ToString().Trim());
        }

        return comments;
    }

    static void Main()
    {
