import threading
import queue
import functools

class SafeUtils:
    def __init__(self):
        self.appQueue = queue.Queue()

    def safeThread(self, timeout=None, queue=None):
        def decorator(func):
            @functools.wraps(func)
            def wrapper(*args, **kwargs):
                result_queue = queue if queue else self.appQueue
                result = []

                def target():
                    try:
                        result.append(func(*args, **kwargs))
                    except Exception as e:
                        result_queue.put(e)

                thread = threading.Thread(target=target)
                thread.start()
                thread.join(timeout)

                if thread.is_alive():
                    raise TimeoutError(f"Function {func.__name__} timed out after {timeout} seconds")

                if result:
                    return result[0]

            return wrapper
        return decorator

