### Solution:
```swift
@propertyWrapper
struct Clamped<T: Comparable> {
    var value: T
    let min: T
    let max: T

    init(wrappedValue: T, min: T, max: T) {
        self.min = min
        self.max = max
        self.value = min(max(wrappedValue, min), max)
    }

    var wrappedValue: T {
        get { value }
        set { value = min(max(newValue, min), max) }
    }
}

