```swift
import Combine

@propertyWrapper
struct CurrencyType {
    private let key: String = "currencyType"
    private let defaultValue: CurrencyType = .bitcoin
    private let currencyTypePublisher = PassthroughSubject<CurrencyType, Never>()

    var wrappedValue: CurrencyType {
        get {
            if let saved: CurrencyType = UserDefaults.standard.getCodable(forKey: key) {
                return saved
            }
            return defaultValue
        }
        set {
            UserDefaults.standard.setCodable(value: newValue, forKey: key)
            currencyTypePublisher.send(newValue)
        }
    }

    var projectedValue: AnyPublisher<CurrencyType, Never> {
        return currencyTypePublisher.eraseToAnyPublisher()
    }
}

enum CurrencyType: String, Codable {
    case bitcoin
    case ethereum
    case litecoin
    // Add more currency types as needed
}

extension UserDefaults {
    func setCodable<T: Encodable>(value: T, forKey key: String) {
        let encoder = JSONEncoder()
        if let encoded = try? encoder.encode(value) {
            self.set(encoded, forKey: key)
        }
    }

    func getCodable<T: Decodable>(forKey key: String) -> T? {
        if let data = self.data(forKey: key) {
            let decoder = JSONDecoder()
            if let decoded = try? decoder.decode(T.self, from: data) {
                return decoded
            }
        }
        return nil
    }
}
```

