public interface BimBoom {
    long bim(long v);
    String boom(String s);
}

public class BimBoomImpl implements BimBoom {
    @Override
    public long bim(long v) {
        if (v > Long.MAX_VALUE - 1000) {
            return -1; // Handle integer overflow
        }
        return v + String.valueOf(v).length();
    }

