import unittest
import re
from functools import wraps

def skipMPI(version):
    def decorator(test_method):
        @wraps(test_method)
        def wrapper(*args, **kwargs):
            mpi_version = get_mpi_version()  # Assume this function retrieves the MPI version
            if mpi_version:
                if compare_versions(mpi_version, version):
                    raise unittest.SkipTest(f"Skipping test for MPI version: {mpi_version}")
            return test_method(*args, **kwargs)
        return wrapper
    return decorator

def get_mpi_version():
