    return "msmpi<8.1.0"  # Example MPI version

def compare_versions(version1, version2):
    pattern = r'(\D+)(\d+)\.(\d+)\.(\d+)'
    match1 = re.match(pattern, version1)
    match2 = re.match(pattern, version2)
    if match1 and match2:
        if match1.group(1) == match2.group(1):
            v1 = tuple(map(int, match1.group(2, 3, 4)))
            v2 = tuple(map(int, match2.group(2, 3, 4)))
            return v1 < v2
    return False

