        "com.fasterxml.jackson.dataformat.xml.annotation.JacksonXmlElementWrapper"})
@SupportedSourceVersion(SourceVersion.RELEASE_8)
public class JacksonXmlAnnotationProcessor extends AbstractProcessor {

    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        for (Element element : roundEnv.getElementsAnnotatedWith(JacksonXmlProperty.class)) {
            if (element.getKind() == ElementKind.FIELD) {
                JacksonXmlProperty annotation = element.getAnnotation(JacksonXmlProperty.class);
                String fieldName = element.getSimpleName().toString();
