class KnowledgeDatabase:
    knowledge_entries = []

    @classmethod
    def add_entry(cls, title, content, image=None):
        entry = {'title': title, 'content': content, 'image': image}
        cls.knowledge_entries.append(entry)

    @classmethod
    def get_entry(cls, title):
        for entry in cls.knowledge_entries:
            if entry['title'] == title:
                if entry['image']:
                    return f"Title: {entry['title']}, Content: {entry['content']}, Image: {entry['image']}"
