def BilinearForm(func):
    def wrapper(*args):
        for arg in args:
            if not isinstance(arg, tuple):
                raise TypeError(f"Argument '{arg}' must be a tuple.")
            for elem in arg:
                if not isinstance(elem, (int, float)) and not isinstance(elem, tuple):
                    raise TypeError(f"Elements of tuple '{arg}' must be numeric values or tuples of numeric values.")
