### Solution:
```cpp
#include <git2.h>

namespace Zero
{
  class Git
  {
  public:
    Git();
    ~Git();
    void initRepository(const std::string& directory);
    void stageFile(const std::string& filePath);
    void commit(const std::string& message);
    void push(const std::string& remote);
  private:
    git_repository* repo;
  };

  Git::Git()
  {
    git_libgit2_init();
  }

  Git::~Git()
  {
    git_libgit2_shutdown();
  }

  void Git::initRepository(const std::string& directory)
  {
    int error = git_repository_init(&repo, directory.c_str(), 0);
    if (error < 0)
    {
      const git_error* e = giterr_last();
      throw std::runtime_error("Error initializing repository: " + std::string(e->message));
    }
  }

  void Git::stageFile(const std::string& filePath)
  {
    git_index* index;
    int error = git_repository_index(&index, repo);
    if (error < 0)
    {
      const git_error* e = giterr_last();
      throw std::runtime_error("Error getting repository index: " + std::string(e->message));
    }

    error = git_index_add_bypath(index, filePath.c_str());
    if (error < 0)
    {
      const git_error* e = giterr_last();
      throw std::runtime_error("Error staging file: " + std::string(e->message));
    }

    git_index_free(index);
  }

  void Git::commit(const std::string& message)
  {
    git_oid tree_id, commit_id;
    git_tree* tree;
    git_index* index;
    git_signature* author;
    git_signature* committer;
    git_commit* parent = nullptr;

    int error = git_repository_index(&index, repo);
    if (error < 0)
    {
      const git_error* e = giterr_last();
      throw std::runtime_error("Error getting repository index: " + std::string(e->message));
    }

    error = git_index_write_tree(&tree_id, index);
    if (error < 0)
    {
      const git_error* e = giterr_last();
      git_index_free(index);
      throw std::runtime_error("Error writing tree: " + std::string(e->message));
    }

    error = git_tree_lookup(&tree, repo, &tree_id);
    if (error < 0)
    {
      const git_error* e = giterr_last();
      git_index_free(index);
      throw std::runtime_error("Error looking up tree: " + std::string(e->message));
    }

    error = git_signature_now(&author, "John Doe", "johndoe@example.com");
    if (error < 0)
    {
      const git_error* e = giterr_last();
      git_index_free(index);
      git_tree_free(tree);
      throw std::runtime_error("Error creating author signature: " + std::string(e->message));
    }

    error = git_signature_now(&committer, "John Doe", "johndoe@example.com");
    if (error < 0)
    {
      const git_error* e = giterr_last();
      git_index_free(index);
      git_tree_free(tree);
      git_signature_free(author);
      throw std::runtime_error("Error creating committer signature: " + std::string(e->message));
    }

    error = git_commit_lookup(&parent, repo, git_reference_target(git_repository_head(repo)));
    if (error < 0 && error != GIT_ENOTFOUND)
    {
      const git_error* e = giterr_last();
      git_index_free(index);
      git_tree_free(tree);
      git_signature_free(author);
      git_signature_free(committer);
      throw std::runtime_error("Error looking up parent commit: " + std::string(e->message));
    }

    error = git_commit_create_v(
      &commit_id, repo, "HEAD", author, committer, "UTF-8", message.c_str(), tree, parent ? 1 : 0, parent);
    if (error < 0)
    {
      const git_error* e = giterr_last();
      git_index_free(index);
      git_tree_free(tree);
      git_signature_free(author);
      git_signature_free(committer);
      if (parent)
        git_commit_free(parent);
      throw std::runtime_error("Error creating commit: " + std::string(e->message));
    }

    git_index_free(index);
    git_tree_free(tree);
    git_signature_free(author);
    git_signature_free(committer);
    if (parent)
      git_commit_free(parent);
  }

  void Git::push(const std::string& remote)
  {
    git_remote* git_remote;
    int error = git_remote_lookup(&git_remote, repo, remote.c_str());
    if (error < 0)
    {
      const git_error* e = giterr_last();
      throw std::runtime_error("Error looking up remote: " + std::string(e->message));
    }

    git_push_options options = GIT_PUSH_OPTIONS_INIT;
    error = git_remote_push(git_remote, nullptr, &options);
    if (error < 0)
    {
      const git_error* e = giterr_last();
      git_remote_free(git_remote);
      throw std::runtime_error("Error pushing to remote: " + std::string(e->message));
    }

    git_remote_free(git_remote);
  }
}
```

