print(processor.extract_tagged_text(tagged_sentence))  # Output: 'Not going to the park'
print(processor.remove_tag(tagged_sentence))  # Output: 'Not going to the park.'
print(processor.replace_tag(tagged_sentence, 'Avoiding the park'))  # Output: 'Avoiding the park.'
```

