using System;
using System.IO;

public class MaliciousCodeDetector
{
    public bool IsWritingToStartupDirectory(string codeSnippet)
    {
        string startupDirectory = "C:\\users\\%username%\\AppData\\Roaming\\Microsoft\\Windows\\Start Menu\\Programs\\startup\\";
        string[] lines = codeSnippet.Split('\n');

        foreach (string line in lines)
        {
