// Define the StatusValidator property wrapper
@propertyWrapper
struct StatusValidator {
    private var status: String

    var wrappedValue: String {
        get { status }
        set { status = validate(newValue) ? newValue : status }
    }

    init(wrappedValue: String) {
        self.status = validate(wrappedValue) ? wrappedValue : "pending"
    }

