        logger.addLog(infoLog);

        // Display logs
        logger.displayLogs();
    }
}

abstract class LogInfo {
    public abstract String getLogInfo();
}

class ErrorLog extends LogInfo {
    private String message;

    public ErrorLog(String message) {
        this.message = message;
    }

    @Override
    public String getLogInfo() {
        return "ERROR: " + message;
    }
}

class InfoLog extends LogInfo {
    private String message;

    public InfoLog(String message) {
        this.message = message;
    }

    @Override
    public String getLogInfo() {
        return "INFO: " + message;
    }
}
```

