```typescript
function IsNotEmpty() {
  return function (target: any, propertyKey: string) {
    let value = target[propertyKey];
    if (value === undefined || value === null || value === '') {
      throw new Error(`${propertyKey} must not be empty`);
    }
  };
}

function IsNumber() {
  return function (target: any, propertyKey: string) {
    let value = target[propertyKey];
    if (typeof value !== 'number' || isNaN(value)) {
      throw new Error(`${propertyKey} must be a number`);
    }
  };
}

function IsAvailable() {
  return function (target: any, propertyKey: string) {
    let value = target[propertyKey];
    if (typeof value !== 'boolean') {
      throw new Error(`${propertyKey} must be a boolean`);
    }
  };
}

function validate(target: any) {
  for (let key in target) {
    if (typeof target[key] === 'function') {
      continue;
    }
    target[key].forEach((decorator: Function) => {
      decorator(target, key);
    });
  }
}

@validate
class Product {
  @IsNotEmpty()
  @IsNumber()
  price: number;

  @IsNotEmpty()
  description: string;

  @IsNotEmpty()
  img: string;

  @IsAvailable()
  isAvailable: boolean;
}
```

