### Solution:
```typescript
// Define the IsString decorator
function IsString() {
  return function (target: any, propertyKey: string) {
    let value = target[propertyKey];

    const getter = function () {
      return value;
    };

    const setter = function (newVal: string) {
      if (typeof newVal !== "string") {
        throw new Error(`Property ${propertyKey} must be a string`);
      }
      value = newVal;
    };

    Object.defineProperty(target, propertyKey, {
      get: getter,
      set: setter,
      enumerable: true,
      configurable: true,
    });
  };
}

// Define the ApiProperty decorator
function ApiProperty(options: { name: string }) {
  return function (target: any, propertyKey: string) {
    // Add metadata to the property
    Reflect.defineMetadata("apiProperty", options, target, propertyKey);
  };
}

// Example usage
class Example {
  @IsString()
  readonly enterpriseAddress: string;

  @ApiProperty({ name: "发行资产数量" })
  @IsString()
  readonly amount: string;
}

