```

### Solution:
```python
import sys

class FileSystem:
    def __init__(self):
        self.root = Directory("/")

    def execute_command(self, command):
        operation, path = command.split(" ", 1)
        if operation == "mkdir":
            return self.create_directory(path)
        elif operation == "touch":
            return self.create_file(path)
        elif operation == "ls":
            return self.list_directory_contents(path)
        else:
            return f"Invalid operation: {operation}"

    def create_directory(self, path):
        directory = self.get_directory(path)
        if directory:
            return f"Directory {path} already exists"
        else:
            parent_path, directory_name = self.split_path(path)
            parent_directory = self.get_directory(parent_path)
            if parent_directory:
                new_directory = Directory(directory_name)
                parent_directory.add_entry(new_directory)
                return f"Output of mkdir {path}"
            else:
                return f"Parent directory {parent_path} does not exist"

    def create_file(self, path):
        directory_path, file_name = self.split_path(path)
        directory = self.get_directory(directory_path)
        if directory:
            new_file = File(file_name)
            directory.add_entry(new_file)
            return f"Output of touch {path}"
        else:
            return f"Directory {directory_path} does not exist"

    def list_directory_contents(self, path):
        directory = self.get_directory(path)
        if directory:
            contents = directory.list_contents()
            return f"Output of ls {path}: {', '.join(contents)}"
        else:
            return f"Directory {path} does not exist"

    def get_directory(self, path):
        if path == "/":
            return self.root
        components = path.split("/")
        current_directory = self.root
        for component in components[1:]:
            if not isinstance(current_directory, Directory):
                return None
            current_directory = current_directory.get_entry(component)
            if current_directory is None:
                return None
        return current_directory

    @staticmethod
    def split_path(path):
        components = path.split("/")
        parent_path = "/".join(components[:-1])
        entry_name = components[-1]
        return parent_path, entry_name

class Entry:
    def __init__(self, name):
        self.name = name

class Directory(Entry):
    def __init__(self, name):
        super().__init__(name)
        self.entries = {}

    def add_entry(self, entry):
        self.entries[entry.name] = entry

    def get_entry(self, name):
        return self.entries.get(name)

    def list_contents(self):
        return list(self.entries.keys())

class File(Entry):
    def __init__(self, name):
        super().__init__(name)

def simulate_file_system(commands):
    file_system = FileSystem()
    output = []
    for command in commands:
        result = file_system.execute_command(command)
        output.append(result)
    return output
